import{_ as a}from"./chunks/daily-2026-08-11-governed-connector-action-handoff-figure.BulGsqYY.js";import{_ as o,C as r,o as i,c as n,E as s,a2 as c}from"./chunks/framework.Cm6XCzck.js";const y=JSON.parse('{"title":"Connector Actions Need a Governed Authority Handoff","description":"","frontmatter":{"title":"Connector Actions Need a Governed Authority Handoff","date":"2026-08-11","column":"industry-architecture","category":"daily","summary":"Connector-mediated actions should distinguish observed availability, action eligibility, user or role authorization, provider submission, provider-confirmed outcome and post-handoff custody instead of collapsing them into one tool-call status.","sources":["research/analysis/Q-20260811-02-connector-action-handoff.md","research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md"],"item_id":"Q-20260811-02","lifecycle":"Published","source_research_object":"research/analysis/Q-20260811-02-connector-action-handoff.md","source_reading_result":"research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md","cover":"/assets/covers/daily-2026-08-11-governed-connector-action-handoff.webp","visualization":"/assets/covers/daily-2026-08-11-governed-connector-action-handoff-figure.svg","visualization_decision":"Required — editorial handoff metaphor plus a separate authority-stage figure","evidence_status":"Completed","citation_status":"Completed","editing_status":"Completed","publication_authorized":true,"outline":"deep"},"headers":[],"relativePath":"en/industry/2026-08-11-governed-connector-action-handoff.md","filePath":"en/industry/2026-08-11-governed-connector-action-handoff.md","lastUpdated":1786455324000}'),d={name:"en/industry/2026-08-11-governed-connector-action-handoff.md"};function l(h,e,u,p,m,f){const t=r("ArticleCover");return i(),n("div",null,[s(t,{image:"/assets/covers/daily-2026-08-11-governed-connector-action-handoff.webp",kicker:"Industry Architecture · Daily Research",title:"Connector Actions Need a Governed Authority Handoff",summary:"Connector-mediated actions should distinguish observed availability, action eligibility, user or role authorization, provider submission, provider-confirmed outcome and post-handoff custody instead of collapsing them into one tool-call status.",version:"Q-20260811-02",status:"Daily Runtime V5 · 2026-08-11",languageHref:"/zh/industry/2026-08-11-governed-connector-action-handoff",languageLabel:"中文"}),e[0]||(e[0]=c('<h1 id="connector-actions-need-a-governed-authority-handoff" tabindex="-1">Connector Actions Need a Governed Authority Handoff <a class="header-anchor" href="#connector-actions-need-a-governed-authority-handoff" aria-label="Permalink to &quot;Connector Actions Need a Governed Authority Handoff&quot;">​</a></h1><p>An agent can observe a live opportunity without owning the transaction that follows. Restaurant reservation support in ChatGPT makes this boundary unusually visible: recommendation, live availability, action eligibility, booking submission and the authoritative reservation record belong to different stages and, in some cases, different systems.</p><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Official OpenAI documentation states that ChatGPT can surface restaurant reservation availability from supported providers and can expose a Reserve action when a restaurant is matched to a supported reservation listing. The booking flow still allows the user to review or change details before the reservation is placed, and after booking the third-party provider remains the authoritative system for confirmation, modification and cancellation.</p><p>The Research Center judgment is that connector actions should be modeled as an <strong>authority handoff</strong>, not as a single <code>tool_call -&gt; success</code> event. A useful action lifecycle distinguishes at least: <code>Observed Availability → Action Eligibility → Authorization → Provider Submission → Provider-confirmed Outcome → External Custody</code>.</p><h2 id="source" tabindex="-1">Source <a class="header-anchor" href="#source" aria-label="Permalink to &quot;Source&quot;">​</a></h2><p>Primary evidence comes from official OpenAI documentation:</p><ul><li>ChatGPT release notes: <a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/6825453-chatgpt-release-notes</a></li><li>ChatGPT Search help: <a href="https://help.openai.com/en/articles/9237897-chatgpt-search" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/9237897-chatgpt-search</a></li></ul><p>The Reading Result records the August 10, 2026 reservation rollout and the documented Reserve-button, user-review, provider-confirmation and post-booking ownership boundaries. Production does not infer undocumented connector protocols or API guarantees.</p><h2 id="observation" tabindex="-1">Observation <a class="header-anchor" href="#observation" aria-label="Permalink to &quot;Observation&quot;">​</a></h2><p>The documented flow separates recommendation from action. A restaurant can be recommendable even when ChatGPT cannot match it to a supported reservation provider, in which case the Reserve action is not exposed. Availability is also explicitly time-sensitive, so a displayed slot is an observation rather than a durable commitment.</p><p>When Reserve is available, the user enters a booking flow and can adjust details before placement. After the reservation is placed, ChatGPT does not keep the booking as the authoritative record. Confirmation, modification, cancellation and provider-account issues remain with the external reservation service.</p><p>The product surface is itself a policy input. The release applies to supported ChatGPT surfaces and explicitly excludes ChatGPT Work, demonstrating that execution eligibility depends on more than model capability alone.</p><p><img src="'+a+'" alt="Connector action authority-handoff figure"></p><p><em>Figure 1. A connector action moves from availability observation through qualification, authorization, and commit before the Provider holds the result and record. Source: Research Center synthesis based on the cited primary sources.</em></p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Authoritative question</th><th>Typical authority</th><th>Evidence class</th></tr></thead><tbody><tr><td>Availability observation</td><td>“Is a slot visible now?”</td><td>Reservation provider data surfaced through ChatGPT</td><td>Official product documentation</td></tr><tr><td>Action eligibility</td><td>“Can this result expose Reserve?”</td><td>Product/provider match + surface policy</td><td>Official documentation</td></tr><tr><td>Authorization</td><td>“May this booking be submitted?”</td><td>User review or explicit role policy</td><td>Official documented user flow + Research Center generalization</td></tr><tr><td>Provider submission</td><td>“Was the request sent to the provider?”</td><td>Connector / provider boundary</td><td>Research Center architecture model; protocol undisclosed</td></tr><tr><td>Provider-confirmed outcome</td><td>“Did the provider accept the transaction?”</td><td>Reservation provider</td><td>Official support/confirmation boundary</td></tr><tr><td>Post-booking custody</td><td>“Who can modify or cancel later?”</td><td>Reservation provider</td><td>Official documentation</td></tr></tbody></table><h2 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h2><p>A connector platform becomes unsafe when it treats every successful tool response as a business outcome. A tool can return current availability without reserving anything. It can open an action surface without the user having authorized submission. It can submit a request without yet receiving provider-confirmed acceptance. And once a provider owns the record, the assistant should not imply it can later modify or cancel that transaction unless a separate governed capability exists.</p><p>This suggests two complementary controls. First, each side-effecting skill should publish a machine-readable <strong>authority descriptor</strong>: observe, propose, submit and lifecycle-manage are different permissions. Second, every cross-system action should produce a handoff receipt that records the external provider, the internal occurrence identity, submitted parameters, provider confirmation or error reference and the current custody owner.</p><p>The system-of-record boundary should be explicit in the UI as well. “Available,” “actionable,” “submitted” and “confirmed” must not collapse into the same status badge.</p><h2 id="engineering-impact" tabindex="-1">Engineering Impact <a class="header-anchor" href="#engineering-impact" aria-label="Permalink to &quot;Engineering Impact&quot;">​</a></h2><p>For Digital Employees, side-effecting connector skills should declare whether they are read-only, proposal-only, submit-capable or authorized for later lifecycle management. Human confirmation or role policy should sit directly at the transition to provider submission.</p><p>For CodeFlowMu, external connector actions should be represented as governed TASK/tool transitions with separate internal task IDs and provider transaction IDs. Runtime timelines should preserve candidate, actionable, submitted and confirmed states so a visible opportunity cannot be mistaken for a completed business action.</p><p>For TMPA, this is useful research evidence for authority transfer, custody and cross-system evidence semantics. The current product documentation, however, does not define a generic connector protocol suitable for direct standardization.</p><h2 id="boundaries-and-uncertainty" tabindex="-1">Boundaries and uncertainty <a class="header-anchor" href="#boundaries-and-uncertainty" aria-label="Permalink to &quot;Boundaries and uncertainty&quot;">​</a></h2><p>The official sources do not disclose the connector API, authentication model, caching strategy, freshness SLA, duplicate-submit protection, payment or deposit handling, provider-login flow or consistency guarantees. The product documentation therefore establishes user-visible authority boundaries, not a complete transactional protocol.</p><h2 id="future-work" tabindex="-1">Future Work <a class="header-anchor" href="#future-work" aria-label="Permalink to &quot;Future Work&quot;">​</a></h2><p>A general agent runtime should define the minimum handoff receipt for an external action and specify how stale availability is revalidated immediately before submission. It should also define provider selection when one business can be represented by multiple providers, and which Digital Employee roles may propose, submit, modify or cancel transactions without a human confirmation step.</p><h2 id="visualization-note" tabindex="-1">Visualization note <a class="header-anchor" href="#visualization-note" aria-label="Permalink to &quot;Visualization note&quot;">​</a></h2><p>The header cover uses two authority domains and one transaction carrier held at a controlled boundary to represent authority transfer. The figure embedded in the Observation section shows the full six-stage handoff lifecycle with bilingual terminology. Both assets are Research Center originals and contain no invented quantitative data.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>OpenAI, ChatGPT release notes, August 10, 2026 reservation availability update: <a href="https://help.openai.com/en/articles/6825453-chatgpt-release-notes" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/6825453-chatgpt-release-notes</a></li><li>OpenAI, ChatGPT Search help, Reserve action and reservation-flow documentation: <a href="https://help.openai.com/en/articles/9237897-chatgpt-search" target="_blank" rel="noreferrer">https://help.openai.com/en/articles/9237897-chatgpt-search</a></li><li>Research Center Research Object: <code>research/analysis/Q-20260811-02-connector-action-handoff.md</code></li><li>Research Center Reading Result: <code>research/reading/Q-20260811-02-restaurant-reservation-action-handoff.md</code></li></ol><blockquote><p>Publication status: Released after the Publication gate; article content is unchanged from the completed Production Candidate.</p></blockquote>',34))])}const g=o(d,[["render",l]]);export{y as __pageData,g as default};
